import BarChart from "@/components/Graph/BarChart.vue";
import { Buffer } from "buffer";
import SnackBar from "@/components/SnackBar.vue";
import { API, graphqlOperation } from "aws-amplify";
import { get_tvboard_details } from "@/graphql/queries.js";
import { formatedatetime } from "@/JsonFiles/DateFormate.js";
export default {
  components: {
    SnackBar,
    BarChart,
    ColoumnChart,
    PieChart,
    DonutChart,
    LineChart,
    OverlayComp
  },
  data() {
    return {
      lastpublished: [],
      SnackBarComponent: {},
      overlay: false,
      activePanel: null,
      htmlContent: "",
      lastPublisedOn: "",
      imageitems: [{
        src: "https://cdn.vuetifyjs.com/images/carousel/squirrel.jpg"
      }, {
        src: "https://cdn.vuetifyjs.com/images/carousel/sky.jpg"
      }, {
        src: "https://cdn.vuetifyjs.com/images/carousel/bird.jpg"
      }, {
        src: "https://cdn.vuetifyjs.com/images/carousel/planet.jpg"
      }]
    };
  },
  created() {
    this.get_dashboard();
  },
  methods: {
    getHeaderClass(panelIndex) {
      return this.activePanel === panelIndex ? false : true;
    },
    async get_dashboard() {
      this.overlay = true;
      try {
        let result = await API.graphql(graphqlOperation(get_tvboard_details, {
          input: {
            tv_board_id: this.$store.getters.GetTvdetails.tv_board_id
          }
        }));
        var response = JSON.parse(result.data.get_tvboard_details);
        if (response.Status == "SUCCESS") {
          this.overlay = false;
          if (response.data[0].message_payload != undefined) {
            this.overlay = false;
            let xapikey = response.data[0].message_payload.data;
            if (xapikey == undefined) {
              this.overlay = false;
              this.lastpublished = [];
              this.htmlContent = "";
            } else {
              this.overlay = false;
              const bufferData = Buffer.from(xapikey);
              const strData = bufferData.toString();
              const api = JSON.parse(strData);
              this.lastPublisedOn = this.fetch_value(response.data[0].last_published_on);
              this.lastpublished = this.transformSectionData(api);
            }
          } else {
            this.overlay = false;
            this.lastpublished = [];
            this.htmlContent = "";
            this.overlay = false;
          }
        } else {
          this.overlay = false;
          this.lastpublished = [];
          this.htmlContent = "";
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.data.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.overlay = false;
        this.lastpublished = [];
        this.htmlContent = "";
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    getRandomColor() {
      const letters = "0123456789ABCDEF";
      let color = "#";
      for (let i = 0; i < 6; i++) {
        color += letters[Math.floor(Math.random() * 16)];
      }
      return color;
    },
    fetch_value(val) {
      return formatedatetime(val / 1000);
    },
    transformSectionData(lastdata) {
      return lastdata.map(section => {
        if (section.section_type === "PIE_CHART") {
          return {
            ...section,
            section_value: [{
              type: "pie",
              startAngle: 240,
              yValueFormatString: '##0.00"%"',
              indexLabel: "{label} {y}",
              dataPoints: section.section_value.map(item => ({
                y: Number(item.value),
                label: item.label
              }))
            }]
          };
        } else if (section.section_type === "DONUT_CHART") {
          return {
            ...section,
            section_value: [{
              type: "doughnut",
              startAngle: 60,
              indexLabelFontSize: 17,
              indexLabel: "{label} - #percent%",
              toolTipContent: "<b>{label}:</b> {y} (#percent%)",
              dataPoints: section.section_value.map(item => ({
                y: Number(item.value),
                label: item.label
              }))
            }]
          };
        }
        // else if (
        //   section.section_type === "BAR_CHART" ||
        //   section.section_type === "COLUMN_CHART"
        // ) {
        //   return {
        //     ...section,
        //     section_value: section.section_value.map((item) => ({
        //       type: section.section_type === "BAR_CHART" ? "bar" : "column",
        //       name: item.label,
        //       color: this.getRandomColor(),
        //       legendText: item.label,
        //       showInLegend: true,
        //       dataPoints: item.x.map((label, index) => ({
        //         label,
        //         y: parseInt(item.y[index], 10), // Convert string to number
        //       })),
        //     })),
        //   };
        // }
        //  else if (section.section_type === "LINE_CHART") {
        //   return {
        //     ...section,
        //     section_value: section.section_value.map((series) => ({
        //       type: "spline",
        //       name: series.label,
        //       showInLegend: true,
        //       dataPoints: series.x.map((xDate, index) => ({
        //         label: xDate,
        //         y: parseInt(series.y[index], 10), // Convert y to a number
        //       })),
        //     })),
        //   };
        // }
        return section;
      });
    }
  }
};
